import test, { beforeEach, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { useTestDb } from "../helpers/db.mjs";

// Publishing by an AI: `<instance>__publish` and `<instance>__unpublish`, generated by the content engine for every content module.
// Rules under test: only an existing draft of the tool's own instance, never an edit of content, same checks as the admin's Publish button,
// follows the approval setting of the access exactly like updates do, journalled without content, rate and size limits, profile assignment, FR/EN parity.
// eslint-disable-next-line react-hooks/rules-of-hooks -- useTestDb is not a React hook
const db = await useTestDb();
const T = await import("@/core/services/mcp/tokens");
const { handleMcpRequest } = await import("@/core/services/mcp/server");
const { listMcpTools, listMcpToolCatalogue } = await import("@/core/platform");
const M = await import("@/core/maintenance/actions");
const Q = await import("@/core/maintenance/requests");
const S = await import("@/core/maintenance/settings");
const P = await import("@/core/services/mcp/profiles");
const { createInstance } = await import("@/core/instanceService");
const { createEntry } = await import("@/core/content/service");
const { setSetting } = await import("@/core/settings");
const { describeRequest } = await import("../../src/app/admin/(panel)/assistants/requestsShared.ts");
const { makeTranslator } = await import("@/core/i18n/dictionary");
const { FIXTURE_MODULES } = await import("../helpers/fixtureModules.mjs");

const owner = { email: "owner@example.org", owner: true };
const blog = FIXTURE_MODULES.find((b) => b.manifest.id === "blog").manifest;
let news; let notes;

beforeEach(async () => {
  await db.reset();
  M.resetMaintenanceState();
  await setSetting("i18n.default", "en");
  await setSetting("i18n.enabled", ["en", "fr"]);
  await db.fixture("blog");
  news = await createInstance(db.prisma, { manifest: blog, nickname: "News", names: { en: "News" } });
  notes = await createInstance(db.prisma, { manifest: blog, nickname: "Notes", names: { en: "Notes" } });
});
after(() => db.close());

const rpc = (token, method, params = {}) => handleMcpRequest(new Request("http://x/api/mcp", { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }) }), listMcpTools);
const listed = async (token) => (await (await rpc(token, "tools/list")).json()).result.tools.map((t) => t.name);
async function call(token, name, args = {}) {
  const body = await (await rpc(token, "tools/call", { name, arguments: args })).json();
  if (body.error) return { error: body.error.message };
  const text = body.result.content[0].text;
  let value; try { value = JSON.parse(text); } catch { value = text; }
  return body.result.isError ? { error: text } : { value };
}
/** A write access with the given tools ticked. */
async function access(grant = ["news__publish", "news__unpublish", "maintenance_request_status"], scope = "write") {
  const token = await T.createToken("Camille", scope, "owner@example.org", { grants: Object.fromEntries(grant.map((g) => [g, true])) });
  return { token, id: await T.findTokenId(token) };
}
async function draft(instance, over = {}) {
  const e = await createEntry(db.prisma, { instanceId: instance.id, locale: "en", title: "Hello", summary: "Short", body: "Text of the page", status: "draft", ...over });
  return e.id;
}
const texts = async (id) => JSON.stringify((await db.prisma.entryTranslation.findMany({ where: { entryId: id }, orderBy: { locale: "asc" } })).map((t) => [t.locale, t.slug, t.title, t.summary, t.body]));
const statusOf = async (id) => (await db.prisma.entry.findUnique({ where: { id } })).status;
const audits = (prefix) => db.prisma.auditLog.findMany({ where: { action: { startsWith: prefix } }, orderBy: { createdAt: "asc" } });

test("tools: every content instance gets publish and unpublish; separate rights, never granted by default, requests (not deletions)", async () => {
  const tools = (await listMcpTools()).filter((t) => /__(un)?publish$/.test(t.name));
  assert.deepEqual(tools.map((t) => t.name).sort(), ["news__publish", "news__unpublish", "notes__publish", "notes__unpublish"]);
  for (const t of tools) assert.deepEqual([t.readOnly, t.default, t.destructive, t.request, t.audited], [false, false, false, true, true], t.name);
  const plain = await T.createToken("Drafts only", "write", "o");
  assert.ok((await listed(plain)).includes("news__create_draft"));
  assert.ok(!(await listed(plain)).some((n) => /publish/.test(n)), "an access with the default rights cannot publish");
});

test("rights: without the box ticked it is an unknown tool; a read-only ceiling blocks it even when ticked", async () => {
  const d = await draft(news);
  const plain = await T.createToken("Drafts only", "write", "o");
  const refused = await call(plain, "news__publish", { id: d });
  const unknown = await call(plain, "news__nope", { id: d });
  assert.match(refused.error, /Unknown tool/);
  assert.equal(refused.error.replace("news__publish", "X"), unknown.error.replace("news__nope", "X"));
  const { token } = await access(["news__publish"], "read");
  assert.ok(!(await listed(token)).includes("news__publish"));
  assert.match((await call(token, "news__publish", { id: d })).error, /Unknown tool/);
  assert.equal(await statusOf(d), "draft");
  assert.equal(await Q.pendingCount(), 0);
});

test("setting \"ask me first\" (the default): a request, nothing published; the owner approves; status through maintenance_request_status", async () => {
  const d = await draft(news);
  const before = await texts(d);
  const { token } = await access();
  const r = (await call(token, "news__publish", { id: d })).value;
  assert.equal(r.status, "pending_approval");
  assert.equal(await statusOf(d), "draft", "nothing is published before the approval");
  assert.deepEqual([r.action, r.plan.entry.instance, r.plan.entry.items.map((i) => i.id)], ["entry_publish", "news", [d]]);
  const status = (await call(token, "maintenance_request_status", { requestId: r.requestId })).value;
  assert.equal(status.status, "pending_approval");
  // the owner reads it in plain words
  const req = await Q.getRequest(r.requestId);
  assert.match(describeRequest(req, makeTranslator("en"), (x) => x), /Publish in "news" \(1\): “Hello”/);
  assert.match(describeRequest(req, makeTranslator("fr"), (x) => x), /Publier dans « news » \(1\)/);
  // the same call again returns the waiting request
  assert.equal((await call(token, "news__publish", { id: d })).value.requestId, r.requestId);
  const done = await M.approveRequest(r.requestId, owner);
  assert.equal(done.ok, true, done.message);
  assert.equal(await statusOf(d), "published");
  assert.equal(await texts(d), before, "the approval changes the status only, never the text");
  assert.equal((await call(token, "maintenance_request_status", { requestId: r.requestId })).value.status, "done");
  const row = await db.prisma.entry.findUnique({ where: { id: d } });
  assert.ok(row.publishedAt instanceof Date);
  // a second approval does nothing
  assert.equal((await M.approveRequest(r.requestId, owner)).ok, false);
});

test("setting \"act without asking\": published at once, no request", async () => {
  const d = await draft(news);
  const { token, id } = await access();
  await S.setApprovalMode(id, "direct");
  const r = (await call(token, "news__publish", { id: d })).value;
  assert.deepEqual([r.status], ["done"]);
  assert.match(r.message, /published in "news"/);
  assert.equal(await statusOf(d), "published");
  assert.equal((await Q.listRequests()).length, 0);
  // and it can be returned to draft the same way, content untouched
  const before = await texts(d);
  assert.equal((await call(token, "news__unpublish", { id: d })).value.status, "done");
  assert.equal(await statusOf(d), "draft");
  assert.equal(await texts(d), before);
});

test("only an existing DRAFT of the tool's own instance: published entries, other instances and unknown ids are refused; content is never overwritten", async () => {
  const mine = await draft(news);
  const theirs = await draft(notes, { title: "Other list" });
  const live = await draft(news, { title: "Already live", status: "published" });
  const { token, id } = await access();
  await S.setApprovalMode(id, "direct");
  assert.match((await call(token, "news__publish", { id: theirs })).error, /entry not found/, "another instance's entry is not found");
  assert.equal(await statusOf(theirs), "draft");
  assert.match((await call(token, "news__publish", { id: "nope" })).error, /entry not found/);
  const was = await texts(live);
  assert.match((await call(token, "news__publish", { id: live })).error, /already published; nothing to do/);
  assert.equal(await texts(live), was);
  assert.match((await call(token, "news__unpublish", { id: mine })).error, /draft already/);
  assert.match((await call(token, "news__publish", {})).error, /Give the "id"/);
  assert.match((await call(token, "news__publish", { id: mine, locale: "xx" })).error, /one of/);
  assert.equal(await statusOf(mine), "draft", "no refusal published anything");
  // several at once: one bad entry refuses the whole call (nothing partial)
  assert.match((await call(token, "news__publish", { ids: [mine, theirs] })).error, /Not published: .*entry not found/);
  assert.equal(await statusOf(mine), "draft");
  assert.equal((await call(token, "news__publish", { ids: [mine] })).value.status, "done");
});

test("same checks as the admin's Publish button: a version without title is refused; a missing language is refused when the list shows each language only when written", async () => {
  const bare = await draft(news, { title: " " });
  const { token, id } = await access();
  await S.setApprovalMode(id, "direct");
  assert.match((await call(token, "news__publish", { id: bare })).error, /version has no title/);
  const oneLanguage = await draft(news);
  // the list falls back to the default language: an English-only entry is fine
  assert.equal((await call(token, "news__publish", { id: oneLanguage, locale: "en" })).value.status, "done");
  // locale asked but not written
  const another = await draft(news, { title: "Second" });
  assert.match((await call(token, "news__publish", { id: another, locale: "fr" })).error, /no fr version yet/);
  // each language must be written
  await db.prisma.moduleInstance.update({ where: { id: news.id }, data: { fallbackToDefault: false } });
  const half = await draft(news, { title: "Half" });
  const err = (await call(token, "news__publish", { id: half })).error;
  assert.match(err, /the fr version is missing/);
  assert.match(err, /nothing was published/);
  assert.equal(await statusOf(half), "draft");
  assert.equal(await Q.pendingCount(), 0, "a refusal never creates a request");
  // add the missing version through the draft tool: now it goes through
  await db.prisma.entryTranslation.create({ data: { entryId: half, instanceId: news.id, locale: "fr", slug: "moitie", title: "Moitié", summary: "", body: "" } });
  assert.equal((await call(token, "news__publish", { id: half })).value.status, "done");
});

test("a draft edited after the request is NOT published on approval (the owner approved what they saw)", async () => {
  const d = await draft(news);
  const { token } = await access();
  const r = (await call(token, "news__publish", { id: d })).value;
  await db.prisma.entryTranslation.updateMany({ where: { entryId: d }, data: { body: "Something else entirely" } });
  const done = await M.approveRequest(r.requestId, owner);
  assert.equal(done.ok, false);
  assert.match(done.message, /changed since the request/);
  assert.equal(await statusOf(d), "draft");
});

test("journal: who, what, when, never the content; the request and its approval are journalled too", async () => {
  const d = await draft(news, { title: "Secret launch title", body: "Private body text" });
  const { token, id } = await access();
  const r = (await call(token, "news__publish", { id: d })).value;
  assert.equal((await audits("mcp.maintenance.request")).length, 1, "the request");
  await M.approveRequest(r.requestId, owner);
  const rows = await db.prisma.auditLog.findMany();
  const publish = rows.filter((x) => x.action === "entry.publish");
  assert.equal(publish.length, 1);
  assert.deepEqual([publish[0].actor, publish[0].actorKind, publish[0].target, publish[0].module, publish[0].instance], ["mcp:Camille", "assistant", `news/${d}`, "blog", "news"]);
  assert.ok(publish[0].createdAt instanceof Date);
  assert.equal((await audits("mcp.maintenance.approve")).length, 1);
  assert.equal((await audits("mcp.maintenance.entry_publish")).length, 1);
  assert.ok(!JSON.stringify(rows).includes("Secret launch title") && !JSON.stringify(rows).includes("Private body text"), "no content in the journal");
  await S.setApprovalMode(id, "direct");
  await call(token, "news__unpublish", { id: d });
  assert.equal((await audits("entry.unpublish")).length, 1);
});

test("limits: 12 actions per hour and per access (shared with the other tools), 12 entries per call", async () => {
  const { token, id } = await access();
  await S.setApprovalMode(id, "direct");
  const many = Array.from({ length: 13 }, (_, i) => `e${i}`);
  assert.match((await call(token, "news__publish", { ids: many })).error, /At most 12 entries/);
  for (let i = 0; i < 11; i++) await call(token, "news__publish", { id: "missing" });
  // 12 calls so far (the oversized one counted): the next is refused
  const last = await call(token, "news__publish", { id: "missing" });
  assert.match(last.error, /Too many maintenance actions/);
});

test("profiles: both tools are assigned to the \"full\" preset only; every tool of the real catalogue is assigned or excluded", async () => {
  const catalogue = await listMcpToolCatalogue();
  const unassigned = catalogue.filter((t) => P.placementOf(t) === "unassigned").map((t) => t.name);
  assert.deepEqual(unassigned, [], "a new core tool must be assigned to a profile or excluded in src/core/services/mcp/profiles.ts");
  for (const name of ["news__publish", "news__unpublish", "notes__publish", "notes__unpublish"]) {
    const tool = catalogue.find((t) => t.name === name);
    assert.equal(P.placementOf(tool), "full", name);
    assert.deepEqual(["read", "assistant", "full"].map((p) => P.profileAllows(p, tool)), [false, false, true], name);
  }
  for (const name of ["maintenance_my_access", "maintenance_catalog_plan"]) assert.equal(P.placementOf(catalogue.find((t) => t.name === name)), "read", name);
  for (const name of ["maintenance_instance_add", "maintenance_skin_set_options"]) assert.equal(P.placementOf(catalogue.find((t) => t.name === name)), "full", name);
  // the create/update draft tools stay in "assistant"
  assert.equal(P.placementOf(catalogue.find((t) => t.name === "news__create_draft")), "assistant");
  const everyTool = [...P.ACCESS_PROFILES.flatMap((p) => P.PROFILE_TOOLS[p]), ...Object.keys(P.PROFILE_EXCLUDED)];
  const coreNames = new Set(catalogue.filter((t) => !t.instanceId).map((t) => t.name));
  assert.deepEqual(everyTool.filter((n) => !coreNames.has(n) && !n.startsWith("rawg_")), [], "no profile lists a tool that does not exist");
});

test("French and English: every right, request and journal text of this feature exists in both languages with the same variables, in plain words", () => {
  const en = JSON.parse(fs.readFileSync("src/locales/en.json", "utf8"));
  const fr = JSON.parse(fs.readFileSync("src/locales/fr.json", "utf8"));
  const keys = Object.keys(en).filter((k) => /^aim\.(tool\.(my_access|catalog_plan|instance_add|skin_set_options|publish|unpublish)|action\.(my_access|catalog_plan|instance_add|skin_set_options|entry_publish|entry_unpublish)|req\.(bundle|bundle\.item|entry_publish|entry_unpublish|instance_add|skin_set_options)|risk\.(instance_add|skin_set_options|entry_publish|entry_unpublish)|publish\.)/.test(k) || /^audit\.action\.entry\.(un)?publish$/.test(k));
  assert.equal(keys.length, 6 + 6 + 6 + 4 + 2 + 2);
  const vars = (s) => [...s.matchAll(/\{(\w+)\}/g)].map((m) => m[1]).sort().join(",");
  for (const k of keys) {
    assert.ok(typeof fr[k] === "string" && fr[k].trim(), `${k} missing in French`);
    assert.equal(vars(fr[k]), vars(en[k]), `${k}: same variables`);
    assert.ok(!/[!]/.test(en[k] + fr[k]) && !/\b(Veuillez|token|jeton|webhook|slug|payload|JSON)\b/i.test(en[k] + fr[k]), `${k}: plain words`);
  }
});
